from collections import Counter

def _orbit(r, c):
    """D4 symmetry orbit on the 32x32 source, cropped to a 30x30 view."""
    todo = [(r, c)]
    seen = {(r, c)}
    while todo:
        y, x = todo.pop()
        for p in ((x, y), (y, 31-x), (31-y, x)):
            if p not in seen:
                seen.add(p)
                todo.append(p)
    return [(y, x) for y, x in seen if 0 <= y < 30 and 0 <= x < 30]

def transform(grid):
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if src[r][c] != 6:
                continue
            orb = _orbit(r, c)
            vals = [src[y][x] for y, x in orb if src[y][x] != 6]
            if vals:
                # All visible symmetry-equivalent cells encode the same color.
                out[r][c] = Counter(vals).most_common(1)[0][0]
                continue
            # If an entire symmetry orbit is occluded, infer the missing
            # value from the nearest exposed boundary around that orbit.
            near = []
            for y, x in orb:
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and src[yy][xx] != 6:
                        near.append(src[yy][xx])
            if near:
                out[r][c] = Counter(near).most_common(1)[0][0]
    return out
